func (s *server) zonesData(ctx context.Context, r *http.Request) (zonesData, error) {
	q := r.URL.Query()
	d := zonesData{Kind: store.ZoneHR, Categories: sport.Categories, Today: localDate(s.now()).Format(time.DateOnly)}
	if q.Get("kind") == store.ZonePower {
		d.Kind = store.ZonePower
	}
	if c, ok := sport.ByID(q.Get("cat")); ok {
		d.Category = c.ID
	}
	weeks := zoneWeeks[0]
	if n, err := strconv.Atoi(q.Get("weeks")); err == nil {
		for _, w := range zoneWeeks {
			if n == w {
				weeks = n
			}
		}
	}
	d.Kinds = []option{{store.ZoneHR, "Herzfrequenz", d.Kind == store.ZoneHR}, {store.ZonePower, "Leistung", d.Kind == store.ZonePower}}
	for _, w := range zoneWeeks {
		d.Weeks = append(d.Weeks, option{strconv.Itoa(w), fmt.Sprintf("%d Wochen", w), w == weeks})
	}

	today := localDate(s.now())
	first := weekStart(today).AddDate(0, 0, -7*(weeks-1))
	f := categoryFilter(d.Category)
	f.From, f.To = first, today.AddDate(0, 0, 1)
	buckets, err := s.Store.ZoneTotals(ctx, f, d.Kind, store.ByWeek)
	if err != nil {
		return d, err
	}
	maxZone := 5
	if d.Kind == store.ZonePower {
		maxZone = 7
	}
	var keys []string
	idx := map[string]int{}
	chart := zoneChart{Kind: d.Kind}
	for i := range weeks {
		k := isoWeekKey(first.AddDate(0, 0, 7*i))
		idx[k] = i
		keys = append(keys, k)
		chart.Labels = append(chart.Labels, k[len(k)-3:])
	}
	totals := make([]float64, maxZone+1)
	chart.Hours = make([][]float64, maxZone)
	for z := 1; z <= maxZone; z++ {
		chart.Zones = append(chart.Zones, z)
		chart.Hours[z-1] = make([]float64, len(keys))
	}
	sum := 0.0
	for _, b := range buckets {
		// Zone 0 is the time below zone 1 (warm-up, stops) and not shown.
		i, ok := idx[b.Key]
		if !ok || b.Zone < 1 || b.Zone > maxZone {
			continue
		}
		chart.Hours[b.Zone-1][i] += round2(b.Seconds / 3600)
		totals[b.Zone] += b.Seconds
		sum += b.Seconds
	}
	if sum == 0 {
		d.Empty = true
	} else {
		for z := 1; z <= maxZone; z++ {
			d.Legend = append(d.Legend, zoneLegend{Zone: z, Hours: hours(totals[z]),
				Share: fmt.Sprintf("%.0f %%", 100*totals[z]/sum)})
		}
		share := func(from, to int) string {
			v := 0.0
			for z := from; z <= min(to, maxZone); z++ {
				v += totals[z]
			}
			return fmt.Sprintf("%.0f %%", 100*v/sum)
		}
		d.Polarized = []loadCard{
			{Label: "Locker (Z1–2)", Value: share(1, 2)},
			{Label: "Mittel (Z3)", Value: share(3, 3)},
			{Label: "Intensiv (Z4+)", Value: share(4, maxZone)},
		}
	}
	b, _ := json.Marshal(chart)
	d.Chart = template.JS(b)

	latest, at, ok, err := s.Store.LatestThresholds(ctx)
	if err != nil {
		return d, err
	}
	if ok {
		d.Latest, d.HasLatest = latest, true
		d.LatestAt = store.Activity{StartTime: at}.LocalStart().Format("02.01.2006")
	}
	overrides, err := s.Store.Overrides(ctx)
	if err != nil {
		return d, err
	}
	for _, o := range overrides {
		v := overrideView{From: o.From.Format(time.DateOnly)}
		switch {
		case o.MaxHR > 0 && o.FTP > 0:
			v.Label = fmt.Sprintf("max. HF %d bpm · FTP %d W", o.MaxHR, o.FTP)
		case o.MaxHR > 0:
			v.Label = fmt.Sprintf("max. HF %d bpm", o.MaxHR)
		default:
			v.Label = fmt.Sprintf("FTP %d W", o.FTP)
		}
		d.Overrides = append(d.Overrides, v)
	}
	return d, nil
}

func round2(v float64) float64 { return math.Round(v*100) / 100 }

// errOverride is a validation error shown next to the form.
type errOverride string

func (e errOverride) Error() string { return string(e) }

// addOverride stores a manual threshold override and re-derives the
// activities from its date on.
func (s *server) addOverride(w http.ResponseWriter, r *http.Request) {
	from, err := time.Parse(time.DateOnly, r.PostFormValue("from"))
	if err != nil {
		http.Error(w, "Bitte ein gültiges Datum angeben.", http.StatusUnprocessableEntity)
		return
	}
	atoi := func(name string, lo, hi int) (int, error) {
		v := r.PostFormValue(name)
		if v == "" {
			return 0, nil
		}
		n, err := strconv.Atoi(v)
		if err != nil || n < lo || n > hi {
			return 0, errOverride(fmt.Sprintf("%s muss zwischen %d und %d liegen.", map[string]string{"max_hr": "Max. HF", "ftp": "FTP"}[name], lo, hi))
		}
		return n, nil
	}
	maxHR, err1 := atoi("max_hr", 120, 230)
	ftp, err2 := atoi("ftp", 50, 600)
	if err := errors.Join(err1, err2); err != nil {
		http.Error(w, err.Error(), http.StatusUnprocessableEntity)
		return
	}
	if maxHR == 0 && ftp == 0 {
		http.Error(w, "Bitte max. HF oder FTP angeben.", http.StatusUnprocessableEntity)
		return
	}
	list, err := s.Store.Overrides(r.Context())
	if err != nil {
		s.serverError(w, "load overrides", err)
		return
	}
	s.changeOverrides(w, r, append(list, store.Override{From: from, MaxHR: maxHR, FTP: ftp}), from)
}

func (s *server) deleteOverride(w http.ResponseWriter, r *http.Request) {
	from, err := time.Parse(time.DateOnly, r.PostFormValue("from"))
	if err != nil {
		http.Error(w, "unknown override", http.StatusBadRequest)
		return
	}
	list, err := s.Store.Overrides(r.Context())
	if err != nil {
		s.serverError(w, "load overrides", err)
		return
	}
	var keep []store.Override
	for _, o := range list {
		if !o.From.Equal(from) {
			keep = append(keep, o)
		}
	}
	s.changeOverrides(w, r, keep, from)
}

// changeOverrides saves the overrides, marks activities from the changed
// date as outdated and starts the reanalysis. While another import runs
// nothing is changed, so the data never stays half re-derived.
func (s *server) changeOverrides(w http.ResponseWriter, r *http.Request, list []store.Override, from time.Time) {
	ctx := r.Context()
	if last := s.Jobs.Last(); last != nil && last.Running {
		http.Error(w, "Gerade läuft ein Import oder eine Neuberechnung. Bitte danach erneut speichern.", http.StatusConflict)
		return
	}
	if err := s.Store.SetOverrides(ctx, list); err != nil {
		s.serverError(w, "save overrides", err)
		return
	}
	n, err := s.Store.MarkOutdatedFrom(ctx, from)
	if err != nil {
		s.serverError(w, "mark outdated", err)
		return
	}
	if n > 0 {
		label := fmt.Sprintf("Neuberechnung ab %s (Schwellen geändert)", from.Format("02.01.2006"))
		err := s.Jobs.Start(label, func(ctx context.Context, report func(importer.Result)) error {
			_, err := s.Importer.Reanalyze(ctx, report)
			return err
		}, nil)
		if err != nil && !errors.Is(err, ErrJobRunning) {
			s.serverError(w, "start reanalysis", err)
			return
		}
	}
	w.Header().Set("HX-Refresh", "true")
	w.WriteHeader(http.StatusNoContent)
}
